// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser.gql;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.eclipse.rdf4j.query.MalformedQueryException;
import org.eclipse.rdf4j.query.parser.gql.GqlLexer.Kind;
import org.eclipse.rdf4j.query.parser.gql.GqlLexer.Token;
import org.junit.jupiter.api.Test;

class GqlLexerTest {

	@Test
	void preservesOffsetsAndQuotedIdentifierCase() {
		List<Token> tokens = GqlLexer.tokenize("mAtCh (Ålice)-[:`urn:knows`]->(b) RETURN `RETURN`");
		assertTrue(tokens.get(0).is("MATCH"));
		assertEquals("Ålice", tokens.get(2).text());
		assertEquals(7, tokens.get(2).offset());
		Token quoted = tokens.get(tokens.size() - 2);
		assertEquals(Kind.QUOTED_IDENTIFIER, quoted.kind());
		assertEquals("RETURN", quoted.text());
		assertFalse(quoted.is("RETURN"));
		assertEquals(Kind.EOF, tokens.getLast().kind());
	}

	@Test
	void decodesDoubledDelimitersAndEscapes() {
		List<Token> tokens = GqlLexer.tokenize("'can''t' `a``b` \"a\"\"b\" 'x\\n\\t\\u00e5\\U01f600\\\\' ");
		assertEquals(List.of("can't", "a`b", "a\"b", "x\n\tå😀\\", ""), texts(tokens));
	}

	@Test
	void rawQuotesKeepBackslashes() {
		assertEquals(List.of("a\\nb", "a\\tb", ""), texts(GqlLexer.tokenize("@'a\\nb' @`a\\tb`")));
	}

	@Test
	void commentsDoNotChangeQuotedText() {
		List<Token> tokens = GqlLexer.tokenize("-- first\nMATCH /* inline */ (a) // another\r\nRETURN '--/*//' ");
		assertEquals(List.of("MATCH", "(", "a", ")", "RETURN", "--/*//", ""), texts(tokens));
		assertEquals(9, tokens.getFirst().offset());
	}

	@Test
	void acceptsUnicodeAndQuotedParameterNames() {
		List<Token> tokens = GqlLexer.tokenize("$name $1 $`has space` $\"other\" αβ á 𐐀");
		assertEquals(List.of("name", "1", "has space", "other", "αβ", "á", "𐐀", ""), texts(tokens));
		for (int i = 0; i < 4; i++) {
			assertEquals(Kind.PARAMETER, tokens.get(i).kind());
		}
	}

	@Test
	void rawDelimitedParameterNamesPreserveBackslashes() {
		List<Token> tokens = GqlLexer.tokenize("$@\"a\\nb\" $@`c\\td`");
		assertEquals(List.of("a\\nb", "c\\td", ""), texts(tokens));
		assertEquals(Kind.PARAMETER, tokens.get(0).kind());
		assertEquals(Kind.PARAMETER, tokens.get(1).kind());
		for (String invalid : List.of("$@", "$@name", "$@'name'")) {
			assertThrows(MalformedQueryException.class, () -> GqlLexer.tokenize(invalid), invalid);
		}
	}

	@Test
	void numbersSeparateLeadingSignsAndKeepExponentSigns() {
		List<Token> tokens = GqlLexer.tokenize("-12 +0.5 .25 1. 2e-5 3E+6");
		assertEquals(List.of("-", "12", "+", "0.5", ".25", "1.", "2e-5", "3E+6", ""), texts(tokens));
		assertEquals(Kind.NUMBER, tokens.get(6).kind());
	}

	@Test
	void takesLongestOperators() {
		assertEquals(List.of("->", "<-", "<=", ">=", "<>", "!=", "||", ":", ".", ",", "[", "]", "{", "}",
				"(", ")", ";", "|", "&", "!", "+", "-", "*", "/", "%", "=", "<", ">", "?", ""),
				texts(GqlLexer.tokenize("-> <- <= >= <> != || : . , [ ] { } ( ) ; | & ! + - * / % = < > ?")));
	}

	@Test
	void errorsIdentifyTheirLocation() {
		MalformedQueryException ex = assertThrows(MalformedQueryException.class,
				() -> GqlLexer.tokenize("MATCH (a)\r\nRETURN 'unterminated"));
		assertTrue(ex.getMessage().contains("line 2, column 8"), ex.getMessage());
	}

	@Test
	void rejectsMalformedQuotedValuesNumbersAndComments() {
		for (String invalid : List.of("'line\nbreak'", "`open", "/* open", "'\\x41'", "'\\uZZZZ'", "'\\U110000'",
				"'\\uD800'", "'\\U00000'", "'trailing\\", "$", "@name", "1e", "1e+", "2word")) {
			assertThrows(MalformedQueryException.class, () -> GqlLexer.tokenize(invalid), invalid);
		}
	}

	@Test
	void boundsInputAndTokenCounts() {
		assertThrows(MalformedQueryException.class, () -> GqlLexer.tokenize(" ".repeat(1_000_001)));
		assertThrows(MalformedQueryException.class, () -> GqlLexer.tokenize("a ".repeat(100_001)));
	}

	private List<String> texts(List<Token> tokens) {
		return tokens.stream().map(Token::text).toList();
	}
}
